const odin_face *odin_face_find(const char *mod)
{
    for (size_t i = 0; i < sizeof g_faces / sizeof g_faces[0]; i++)
        if (!strcmp(g_faces[i]->mod, mod)) return g_faces[i];
    return NULL;
}

int odin_face_known(const char *mod)
{
    return odin_face_find(mod) != NULL;
}
